"""Load configuration from files and strings."""

import os

from miniconf.errors import ConfigError
from miniconf.parser import parse_lines

_DIRECTIVE = "@include"


def _include_target(line):
    """Return the include path in ``line``, ``None`` if not an include."""
    parts = line.strip().split(None, 1)
    if not parts or parts[0] != _DIRECTIVE:
        return None
    if len(parts) < 2 or not parts[1].strip():
        raise ConfigError("@include requires a path")
    return parts[1].strip()


def _read_expanded(path, stack):
    real = os.path.realpath(path)
    if real in stack:
        raise ConfigError("include cycle detected at {}".format(path))
    with open(path, "r", encoding="utf-8") as fh:
        lines = fh.read().splitlines()
    stack = stack + (real,)
    base = os.path.dirname(real)
    out = []
    for line in lines:
        target = _include_target(line)
        if target is None:
            out.append(line)
            continue
        full = os.path.join(base, target)
        if not os.path.isfile(full):
            raise ConfigError(
                "included file not found: {} (from {})".format(target, path)
            )
        try:
            out.extend(_read_expanded(full, stack))
        except (OSError, UnicodeDecodeError) as exc:
            raise ConfigError(
                "cannot read included file {}: {}".format(target, exc)
            )
    return out


def load(path):
    """Read and parse the configuration file at ``path``.

    ``@include <path>`` lines are replaced inline by the contents of the
    referenced file, resolved relative to the including file's directory.
    """
    return parse_lines(_read_expanded(path, ()))


def loads(text):
    """Parse configuration from a string."""
    return parse_lines(text.splitlines())
